args.script:
(async () => {
  const at = Number(localStorage.getItem('abx_bearer_at') || 0);
  const cur = localStorage.getItem('abx_bearer') || '';
  const fresh = cur && at && (Date.now() - at) < 12 * 3600e3;
  if (fresh) return JSON.stringify({ok: true, src: 'cached', len: cur.length});
  const src = [...document.querySelectorAll("script[src*='main']")].map(s => s.src)[0];
  if (!src) return JSON.stringify({ok: !!cur, src: 'kept-no-main', len: cur.length});
  const t = await (await fetch(src, {credentials: 'omit'})).text();
  const m = t.match(/Bearer ([A-Za-z0-9%/+=]{80,})/);
  if (!m) return JSON.stringify({ok: !!cur, src: 'kept-no-match', len: cur.length});
  localStorage.setItem('abx_bearer', m[1]);
  localStorage.setItem('abx_bearer_at', String(Date.now()));
  return JSON.stringify({ok: true, src: 'refreshed', len: m[1].length});
})()

// x-read step: tweet thread (TweetDetail) or user lookup (UserByScreenName) — read-only, bearer+ct0 only
(async () => {
  const ARGS = {{args_json}};
  try {
    const bearer = localStorage.getItem('abx_bearer');
    const ct0 = (document.cookie.match(/(?:^|;\s*)ct0=([^;]+)/) || [])[1];
    if (!bearer || !ct0) return JSON.stringify({ok: false, err: 'missing bearer/ct0 - session not logged in'});
    const base = {
      'authorization': 'Bearer ' + bearer,
      'x-twitter-auth-type': 'OAuth2Session',
      'x-csrf-token': ct0,
      'x-twitter-client-language': 'en',
      'x-twitter-active-user': 'yes'
    };
    if (ARGS.screen_name) {
      const feats = {responsive_web_graphql_timeline_navigation_enabled: true, verified_phone_label_enabled: true, hidden_profile_subscriptions_enabled: true};
      const q = '/i/api/graphql/KybxDj9RrADIITXlGG8kpw/UserByScreenName?variables=' +
        encodeURIComponent(JSON.stringify({screen_name: ARGS.screen_name, withAuxiliaryUserLabels: true})) +
        '&features=' + encodeURIComponent(JSON.stringify(feats));
      const r = await fetch(q, {credentials: 'include', headers: base});
      const t = await r.text();
      let j = null; try { j = JSON.parse(t); } catch {}
      const u = j && j.data && j.data.user && j.data.user.result;
      if (!r.ok || !u) return JSON.stringify({ok: false, mode: 'user', status: r.status, err_head: t.slice(0, 160)});
      return JSON.stringify({ok: true, mode: 'user', user: {
        id: u.rest_id,
        screen_name: u.core && u.core.screen_name,
        name: u.core && u.core.name,
        created_at: u.core && u.core.created_at,
        blue: !!u.is_blue_verified,
        followers: u.relationship_counts && u.relationship_counts.followers,
        following: u.relationship_counts && u.relationship_counts.following,
        tweets: u.tweet_counts && u.tweet_counts.tweets,
        bio: u.profile_bio && u.profile_bio.description,
        location: u.location && u.location.location,
        persp: u.relationship_perspectives ? {
          following: !!u.relationship_perspectives.following,
          followed_by: !!u.relationship_perspectives.followed_by,
          blocking: !!u.relationship_perspectives.blocking,
          muting: !!u.relationship_perspectives.muting
        } : null
      }});
    }
    if (ARGS.tweet_id) {
      const features = JSON.parse(localStorage.getItem('abx_ct_features'));
      const variables = {focalTweetId: String(ARGS.tweet_id), withRuxInjections: false, includePromotedContent: true,
        withCommunityNoteHydrationEnabled: false, withBirdwatchNotes: false, withVoice: true,
        withSuperFollowsUserFields: false, withDownvotePerspective: false, withReactionsMetadata: false,
        withReactionsPerspective: false, withSuperFollowsTweetFields: false, withBirdwatchPivots: false};
      const q = '/i/api/graphql/FyR-GrebyjdkRoW1z6uCgQ/TweetDetail?variables=' +
        encodeURIComponent(JSON.stringify(variables)) + '&features=' + encodeURIComponent(JSON.stringify(features));
      const r = await fetch(q, {credentials: 'include', headers: base});
      const t = await r.text();
      let j = null; try { j = JSON.parse(t); } catch {}
      if (!r.ok) return JSON.stringify({ok: false, mode: 'tweet', status: r.status, err_head: t.slice(0, 160)});
      let uid = localStorage.getItem('abx_uid');
      const argUid = '{{uid}}';
      if (!uid && argUid) { uid = argUid; localStorage.setItem('abx_uid', uid); }
      let root = null; const replies = []; const mine = [];
      const pick = (ic, isRoot) => {
        const res = ic && ic.tweet_results && ic.tweet_results.result;
        if (!res) return null;
        const core = res.__typename === 'TweetWithVisibilityResults' ? res.tweet : res;
        if (!core || !core.legacy) return null;
        const u = core.core && core.core.user_results && core.core.user_results.result;
        const rec = {
          id: core.legacy.id_str,
          sn: u ? ((u.core && u.core.screen_name) || (u.legacy && u.legacy.screen_name)) : null,
          uid: u ? u.rest_id : null,
          text: core.legacy.full_text,
          fav: core.legacy.favorite_count
        };
        if (isRoot && !root) root = rec;
        return rec;
      };
      const walk = (entries) => {
        for (const e of (entries || [])) {
          const cc = e && e.content;
          if (!cc) continue;
          if (cc.itemContent) { const x = pick(cc.itemContent, !root); if (x && x !== root) replies.push(x); }
          if (cc.items) for (const it of cc.items) { const x = pick(it.item && it.item.itemContent, false); if (x) replies.push(x); }
        }
      };
      for (const ins of ((j.data && j.data.threaded_conversation_with_injections_v2 && j.data.threaded_conversation_with_injections_v2.instructions) || [])) walk(ins.entries);
      for (const x of replies) if (uid && x.uid === uid) mine.push(x.id);
      if (root && uid && root.uid === uid) mine.push(root.id);
      return JSON.stringify({ok: true, mode: 'tweet',
        root: root && {id: root.id, sn: root.sn, fav: root.fav, text: root.text},
        replies: replies.slice(0, 20).map(x => ({sn: x.sn, fav: x.fav, text: x.text.slice(0, 120)})),
        mine_in_thread: mine});
    }
    return JSON.stringify({ok: false, err: 'args_json needs tweet_id or screen_name'});
  } catch (e) {
    return JSON.stringify({ok: false, err: e.name + ': ' + e.message});
  }
})()
